// Protocol abstraction layer. This module must only depend on std/tokio
// types (ARCHITECTURE section 1.1): it must not know about http, store or
// throttle. It is the V2 landing point for additional engines (BT etc.)
// implementing the same Downloader trait.

use async_trait::async_trait;
use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use tokio::sync::mpsc;

/// Task identifier (uuid v4, generated by the engine).
pub type TaskId = String;

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum TaskStatus {
    Pending,
    Downloading,
    Paused,
    Failed,
    Completed,
}

impl TaskStatus {
    pub fn as_str(&self) -> &'static str {
        match self {
            TaskStatus::Pending => "pending",
            TaskStatus::Downloading => "downloading",
            TaskStatus::Paused => "paused",
            TaskStatus::Failed => "failed",
            TaskStatus::Completed => "completed",
        }
    }

    pub fn parse(s: &str) -> Option<TaskStatus> {
        match s {
            "pending" => Some(TaskStatus::Pending),
            "downloading" => Some(TaskStatus::Downloading),
            "paused" => Some(TaskStatus::Paused),
            "failed" => Some(TaskStatus::Failed),
            "completed" => Some(TaskStatus::Completed),
            _ => None,
        }
    }

    pub fn is_terminal(&self) -> bool {
        matches!(self, TaskStatus::Failed | TaskStatus::Completed)
    }
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TaskFilter {
    All,
    Downloading,
    Completed,
    Failed,
}

/// Input for creating a task.
#[derive(Debug, Clone)]
pub struct NewTask {
    pub url: String,
    pub filename: Option<String>,
    pub dir: Option<PathBuf>,
    pub headers: Vec<(String, String)>,
    pub segments: Option<u8>,
}

/// Metadata probed from a direct link (add-task dialog, AC-01).
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ProbeResult {
    pub filename: String,
    pub total_size: Option<u64>,
    pub accept_ranges: bool,
    pub etag: Option<String>,
    pub last_modified: Option<String>,
    pub final_url: String,
}

/// Engine-side view of a task, returned by list and control commands.
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct TaskSnapshot {
    pub id: TaskId,
    pub url: String,
    pub final_url: String,
    pub filename: String,
    pub dir: PathBuf,
    pub total_bytes: Option<u64>,
    pub status: TaskStatus,
    pub speed_limit: Option<u64>,
    pub error: Option<String>,
    pub retry_count: u32,
    pub downloaded_bytes: u64,
    pub created_at: i64,
    pub updated_at: i64,
}

#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct SegmentProgress {
    pub index: u32,
    pub downloaded: u64,
    pub total: u64,
}

/// One 4Hz progress frame (Rust producer-side throttling, Spec 5.3).
#[derive(Debug, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ProgressFrame {
    pub task_id: TaskId,
    pub downloaded_bytes: u64,
    pub total_bytes: Option<u64>,
    pub speed_bps: u64,
    pub eta_secs: Option<u64>,
    pub segments: Vec<SegmentProgress>,
}

/// Machine-readable failure codes carried by `EngineEvent::StateChanged`.
///
/// Single definition point: the fail sites, the event, and the bridge layer
/// all reference this constant, so a consumer can branch on `code` instead of
/// searching the message text. Codes use the same vocabulary as
/// `AppError::code` in the bridge layer.
pub const CODE_RESUME_CONFLICT: &str = "resume_conflict";

/// Events exported by the engine. Lifecycle events travel on an unbounded
/// channel (low frequency, must not be lost); progress frames travel on a
/// bounded channel where a full queue drops frames instead of blocking.
#[derive(Debug, Clone)]
pub enum EngineEvent {
    TaskCreated { task_id: TaskId },
    TaskRemoved { task_id: TaskId },
    StateChanged {
        task_id: TaskId,
        from: TaskStatus,
        to: TaskStatus,
        error: Option<String>,
        /// Structured counterpart of `error`: consumers must branch on this
        /// when present, because the message text is user-facing Chinese copy
        /// and may be reworded at any time (see CODE_RESUME_CONFLICT).
        code: Option<String>,
    },
    Progress(ProgressFrame),
}

/// The two-channel subscription handed to the bridge layer.
pub struct EventSubscriber {
    pub lifecycle: mpsc::UnboundedReceiver<EngineEvent>,
    pub progress: mpsc::Receiver<ProgressFrame>,
}

/// Shared global statistics cache: written by the 4Hz progress aggregator,
/// read by the 1Hz tray tooltip. Independent timers, shared data source.
pub struct GlobalStats {
    active_tasks: std::sync::atomic::AtomicU64,
    total_speed_bps: std::sync::atomic::AtomicU64,
}

impl GlobalStats {
    pub fn new() -> Self {
        Self {
            active_tasks: std::sync::atomic::AtomicU64::new(0),
            total_speed_bps: std::sync::atomic::AtomicU64::new(0),
        }
    }

    pub fn store(&self, active: u64, total_speed_bps: u64) {
        use std::sync::atomic::Ordering;
        self.active_tasks.store(active, Ordering::Relaxed);
        self.total_speed_bps.store(total_speed_bps, Ordering::Relaxed);
    }

    /// Reset the cached values (clear_stats command; the 4Hz aggregator
    /// repopulates live tasks on its next tick).
    pub fn clear(&self) {
        self.store(0, 0);
    }

    pub fn snapshot(&self) -> (u64, u64) {
        use std::sync::atomic::Ordering;
        (
            self.active_tasks.load(Ordering::Relaxed),
            self.total_speed_bps.load(Ordering::Relaxed),
        )
    }
}

impl Default for GlobalStats {
    fn default() -> Self {
        Self::new()
    }
}

/// Persisted user configuration (DB `config` table, JSON values).
#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EngineConfig {
    pub download_dir: PathBuf,
    pub default_segments: u8,
    pub global_speed_limit_bps: Option<u64>,
    pub notify_on_complete: bool,
    /// Close-to-tray switch (DESIGN 4.2): true = CloseRequested hides the
    /// window, false = the app exits. serde default keeps configs saved by
    /// older builds loadable.
    #[serde(default = "default_minimize_to_tray")]
    pub minimize_to_tray: bool,
}

fn default_minimize_to_tray() -> bool {
    true
}

impl Default for EngineConfig {
    fn default() -> Self {
        let download_dir = std::env::var_os("USERPROFILE")
            .map(PathBuf::from)
            .map(|home| home.join("Downloads"))
            .unwrap_or_else(|| PathBuf::from("."));
        Self {
            download_dir,
            default_segments: crate::consts::DEFAULT_SEGMENTS,
            global_speed_limit_bps: None,
            notify_on_complete: true,
            minimize_to_tray: true,
        }
    }
}

/// Partial configuration update for set_config.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct EngineConfigPatch {
    pub download_dir: Option<PathBuf>,
    pub default_segments: Option<u8>,
    pub global_speed_limit_bps: Option<Option<u64>>,
    pub notify_on_complete: Option<bool>,
    pub minimize_to_tray: Option<bool>,
}

/// Engine error taxonomy. The bridge layer maps each variant onto the
/// AppError code enum locked in ARCHITECTURE section 3.2.
#[derive(Debug, thiserror::Error)]
pub enum EngineError {
    #[error("invalid url: {0}")]
    InvalidUrl(String),
    #[error("invalid argument: {0}")]
    InvalidArgument(String),
    #[error("task not found: {0}")]
    TaskNotFound(String),
    #[error("probe failed: {0}")]
    ProbeFailed(String),
    #[error("HTTP status {0}")]
    HttpStatus(u16),
    #[error("resume conflict: {0}")]
    ResumeConflict(String),
    #[error("io error: {0}")]
    Io(String),
    #[error("db error: {0}")]
    Db(String),
    #[error("engine error: {0}")]
    Engine(String),
}

impl From<std::io::Error> for EngineError {
    fn from(e: std::io::Error) -> Self {
        EngineError::Io(e.to_string())
    }
}

/// The downloader protocol. V2 engines (BT etc.) implement the same trait so
/// the bridge layer and the frontend need zero changes (ARCHITECTURE 1.1).
#[async_trait]
pub trait Downloader: Send + Sync + 'static {
    /// Probe direct-link metadata for the add-task dialog (AC-01, 2s).
    async fn probe(&self, url: &str, headers: &[(String, String)]) -> Result<ProbeResult, EngineError>;

    /// Create a task and enqueue it.
    async fn add_task(&self, task: NewTask) -> Result<TaskId, EngineError>;

    async fn pause(&self, id: &TaskId) -> Result<TaskSnapshot, EngineError>;
    async fn resume(&self, id: &TaskId) -> Result<TaskSnapshot, EngineError>;
    async fn retry(&self, id: &TaskId) -> Result<TaskSnapshot, EngineError>;
    async fn remove(&self, id: &TaskId, delete_files: bool) -> Result<(), EngineError>;
    async fn pause_all(&self) -> Result<(), EngineError>;
    async fn resume_all(&self) -> Result<(), EngineError>;

    /// Synchronous DB read (internally spawn_blocking isolated).
    async fn list(&self, filter: TaskFilter) -> Result<Vec<TaskSnapshot>, EngineError>;

    /// Speed limit hot adjustment (effective immediately, AC-12).
    async fn set_global_limit(&self, bytes_per_sec: Option<u64>) -> Result<(), EngineError>;
    async fn set_task_limit(&self, id: &TaskId, bytes_per_sec: Option<u64>) -> Result<(), EngineError>;

    /// Event subscription: (lifecycle stream, progress frame stream).
    fn subscribe(&self) -> EventSubscriber;

    /// Startup recovery: read DB, validate .part files, reset non-terminal
    /// tasks to pending. Returns the number of restored tasks.
    async fn restore(&self) -> Result<usize, EngineError>;

    /// Graceful shutdown: pause all, flush a final snapshot.
    async fn shutdown(&self) -> Result<(), EngineError>;

    /// Config persistence (DB `config` table).
    async fn get_config(&self) -> Result<EngineConfig, EngineError>;
    async fn set_config(&self, patch: EngineConfigPatch) -> Result<EngineConfig, EngineError>;
}
